using CodEat.Web;
using Xunit;
namespace CodEat.Tests;
public class KitchenTests {
 static Recipe Recipe()=>new(){Title="Poisson",Steps="Cuire.",Servings=4,AllergensVerified=true,Ingredients=[new("riz",1,"kg","Épicerie")]};
 [Fact] public void OnePreparationFeedsTwoMealsAndIsCountedOnce(){var d=new WeekData();var p=new Preparation{Recipe=Recipe(),Portions=4};d.Preparations.Add(p);Kitchen.Assign(d,new(0,"Midi",p.Id,2));Kitchen.Assign(d,new(1,"Soir",p.Id,2));Kitchen.Regenerate(d);Assert.Equal(1000,d.Shopping.Single().Calculated);Assert.Throws<InvalidOperationException>(()=>Kitchen.Assign(d,new(2,"Midi",p.Id,1)));}
 [Fact] public void CompatibleUnitsMergeAndDecisionsSurvive(){var r=Recipe();r.Ingredients=[new("riz",1,"kg","Épicerie"),new("riz",200,"g","Épicerie"),new("riz",1,"pièce","Épicerie")];var p=new Preparation{Recipe=r,Portions=2};var d=new WeekData{Preparations=[p],Meals=[new(0,"Midi",p.Id,2)]};Kitchen.Regenerate(d);Assert.Equal(2,d.Shopping.Count);var mass=d.Shopping.Single(x=>x.Unit=="g");Assert.Equal(600,mass.Calculated);mass.Checked=true;mass.Adjusted=550;d.Shopping.Add(new(){Name="Pain",Manual=true});Kitchen.Regenerate(d);Assert.True(d.Shopping.Single(x=>x.Unit=="g").Checked);Assert.False(d.Shopping.Single(x=>x.Unit=="g").Changed);p.Portions=4;Kitchen.Regenerate(d);Assert.True(d.Shopping.Single(x=>x.Unit=="g").Changed);Assert.Contains(d.Shopping,x=>x.Name=="Pain");}
 [Fact] public void UnknownValuesAndUnverifiedAllergensAreExcluded(){var r=Recipe();Assert.False(new RecipeFilter(MaxKcal:500).Matches(r));Assert.False(new RecipeFilter(MaxActive:20).Matches(r));r.AllergensVerified=false;Assert.False(new RecipeFilter(Allergens:"lait").Matches(r));r.AllergensVerified=true;Assert.True(new RecipeFilter(Allergens:"lait").Matches(r));r.Allergens="lait";Assert.False(new RecipeFilter(Allergens:"lait").Matches(r));}
 [Theory][InlineData(1,2)][InlineData(2,2)][InlineData(12,2)][InlineData(6,1)] public void WinterReminder(int month,decimal expected){var rule=new ReminderRule{Quantity=1,WinterQuantity=2};Assert.Equal(expected,Kitchen.Due(rule,new(2026,month,15)).Quantity);Assert.Equal(Kitchen.Due(rule,new(2026,month,1)).Period,Kitchen.Due(rule,new(2026,month,28)).Period);}
 [Fact] public void MonthlyExceptionHasPriority(){var rule=new ReminderRule{Quantity=1,WinterQuantity=2,ExceptionMonth=12,MonthQuantity=3};Assert.Equal(3,Kitchen.Due(rule,new(2026,12,15)).Quantity);}
 [Fact] public void StorageWarningsAreExplicit(){var d=new WeekData();var p=new Preparation{Recipe=Recipe(),At=new(2026,11,15,16,0,0)};d.Preparations.Add(p);d.Meals.Add(new(1,"Soir",p.Id,2));Assert.Contains(Kitchen.Warnings(p,d,new(2026,11,16)),x=>x.Contains("renseigner"));p.Recipe.FridgeHours=24;Assert.Contains(Kitchen.Warnings(p,d,new(2026,11,16)),x=>x.Contains("dépassée"));p.Frozen=true;Assert.Contains(Kitchen.Warnings(p,d,new(2026,11,16)),x=>x.Contains("Congélation"));}
 [Fact] public void NoApproximateIngredientMerge(){var r=Recipe();r.Ingredients=[new("lait",1,"l","Frais"),new("lait de coco",1,"l","Frais")];var p=new Preparation{Recipe=r};var d=new WeekData{Preparations=[p],Meals=[new(0,"Midi",p.Id,2)]};Kitchen.Regenerate(d);Assert.Equal(2,d.Shopping.Count);}
}
